        rs = [r for r in range(h) if grid[r][c] == 5]
        if len(rs) >= 2 and rs == list(range(min(rs), max(rs) + 1)):
            r0, r1 = min(rs), max(rs)
            right = c + 1
            band_rows = [r for r in range(h) if any(grid[r][j] != 0 for j in range(right, w))]
            # Use the contiguous nonzero band immediately beside the guide.
            if band_rows:
                a, b = min(band_rows), max(band_rows)
                for r in range(r0, r1 + 1):
                    for j in range(right, w):
                        out[r][j] = grid[a + (r - a) % (b - a + 1)][j]

    # A horizontal 5 guide; repeat a vertical color pattern immediately below
    # its left end across the full guide.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == 5]
        if len(cs) >= 2 and cs == list(range(min(cs), max(cs) + 1)):
            c0, c1 = min(cs), max(cs)
            below = r + 1
            band_cols = [c for c in range(c0, c1 + 1) if any(grid[i][c] != 0 for i in range(below, h))]
            if band_cols:
                c = min(band_cols)
                band_rows = [i for i in range(below, h) if grid[i][c] != 0]
                if band_rows:
