def transform(grid):
    """Extend color patterns beside straight 5-guides across their lengths."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Horizontal guides: a colored stripe attached beyond an endpoint is
    # copied across the guide's span, one color per perpendicular row.
    for r in range(h):
        for c0, c1 in _runs([grid[r][c] == 5 for c in range(w)]):
            if c1 - c0 + 1 < 2:
                continue
            for c in (c0, c1):
                for dr in (-1, 1):
                    rr = r + dr
                    if not (0 <= rr < h) or grid[rr][c] == 0 or grid[rr][c] == 5:
                        continue
                    vals = []
                    while 0 <= rr < h and grid[rr][c] not in (0, 5):
                        vals.append((rr, grid[rr][c]))
                        rr += dr
                    for sr, color in vals:
                        for cc in range(c0, c1 + 1):
                            if out[sr][cc] == 0:
                                out[sr][cc] = color

    # Vertical guides: take the colored block abutting one side at either
    # endpoint, then repeat its row-pattern along the 5-guide.
    for c in range(w):
        for r0, r1 in _runs([grid[r][c] == 5 for r in range(h)]):
            if r1 - r0 + 1 < 2:
                continue
            for side in (-1, 1):
                sc = c + side
                if not (0 <= sc < w):
                    continue
                for end, inward in ((r0, 1), (r1, -1)):
                    rr = end
                    block = []
                    while r0 <= rr <= r1:
                        # Read the contiguous colored stripe starting beside
                        # the guide, allowing its width to vary by row.
                        cc = sc
                        row_pattern = []
                        step = side
                        while 0 <= cc < w and grid[rr][cc] not in (0, 5):
                            row_pattern.append((cc, grid[rr][cc]))
                            cc += step
                        if not row_pattern:
                            break
                        block.append(row_pattern)
                        rr += inward
                    if not block:
                        continue
                    depth = len(block)
                    # block[0] is at the endpoint; reverse it into increasing
                    # row order for periodic indexing.
                    if inward == -1:
                        block.reverse()
