def transform(grid):
    """Extend color stripes from a 5-guide's endpoint across its length."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A horizontal guide is paired with a perpendicular color run just beyond
    # an endpoint; copy each color across the guide's span.
    for r in range(h):
        for c0, c1 in _runs([grid[r][c] == 5 for c in range(w)]):
            if c1 - c0 + 1 < 2:
                continue
            for endpoint in (c0, c1):
                for dr in (-1, 1):
                    rr = r + dr
                    if not (0 <= rr < h) or grid[rr][endpoint] in (0, 5):
                        continue
                    stripe = []
                    while 0 <= rr < h and grid[rr][endpoint] not in (0, 5):
                        stripe.append((rr, grid[rr][endpoint]))
                        rr += dr
                    for sr, color in stripe:
                        for cc in range(c0, c1 + 1):
                            if out[sr][cc] == 0:
                                out[sr][cc] = color

    # A vertical guide is paired with a one-or-more-row colored block beside
    # one endpoint. Repeat those source row-patterns along the guide.
    for c in range(w):
        for r0, r1 in _runs([grid[r][c] == 5 for r in range(h)]):
            if r1 - r0 + 1 < 2:
                continue
            for endpoint, inward in ((r0, 1), (r1, -1)):
                for side in (-1, 1):
                    sc = c + side
                    if not (0 <= sc < w) or grid[endpoint][sc] in (0, 5):
                        continue
                    source_rows = []
                    rr = endpoint
                    while r0 <= rr <= r1 and grid[rr][sc] not in (0, 5):
                        cells = []
                        cc = sc
                        while 0 <= cc < w and grid[rr][cc] not in (0, 5):
                            cells.append((cc, grid[rr][cc]))
                            cc += side
                        source_rows.append(cells)
                        rr += inward
                    if not source_rows:
                        continue
                    for tr in range(r0, r1 + 1):
                        index = (endpoint - tr) % len(source_rows) if inward == -1 else (tr - endpoint) % len(source_rows)
                        for cc, color in source_rows[index]:
                            if out[tr][cc] == 0:
                                out[tr][cc] = color
    return out
